from typing import List

def bird_code(bird_names: List[str]) -> List[str]:
    result = []
    for name in bird_names:
        normalized = name.replace('-', ' ')
        words = normalized.split()
        num_words = len(words)

        if num_words == 1:
            code = words[0][:4].upper()
        elif num_words == 2:
            code = (words[0][:2] + words[1][:2]).upper()
        elif num_words == 3:
            code = (words[0][:1] + words[1][:1] + words[2][:2]).upper()
        elif num_words == 4:
            code = (words[0][:1] + words[0][:1] + words[1][:1] + words[1][:1] + words[2][:1] + words[3][:1])
            code = (words[0][0] + words[1][0] + words[2][0] + words[3][0]).upper()
        else:
            code = ""

        result.append(code)

    return result
